{
 "app_name": "splitwise",
 "api_name": "show_activity",
 "path": "/account/activity",
 "method": "GET",
 "description": "Show a history of your expenses and payments combined.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "show_expenses",
   "type": "boolean",
   "required": false,
   "description": "Whether to show expenses in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "show_payments",
   "type": "boolean",
   "required": false,
   "description": "Whether to show payments in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the expenses/payments by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at.",
   "default": "-created_at",
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "record_type": "expense",
    "amount": 0.0,
    "paid_by": {
     "name": "string",
     "email": "user@example.com"
    },
    "owed_by": [
     {
      "name": "string",
      "email": "user@example.com",
      "amount": 0.0
     }
    ],
    "description": "string",
    "group_id": 1,
    "group_name": "string",
    "created_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "splitwise",
 "api_name": "show_group_expenses",
 "path": "/group/{group_id}/expenses",
 "method": "GET",
 "description": "Show or search your expenses from a given group based on various criteria.",
 "parameters": [
  {
   "name": "group_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the group to filter expenses.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "participant_email",
   "type": "string",
   "required": false,
   "description": "Email of the payer or debtors to filter expenses.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "min_amount",
   "type": "number",
   "required": false,
   "description": "Filter expenses by minimum amount.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "max_amount",
   "type": "number",
   "required": false,
   "description": "Filter expenses by maximum amount.",
   "default": 9223372036854775807,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "min_created_at",
   "type": "string",
   "required": false,
   "description": "Filter emails by minimum created_at date in YYYY-MM-DD format.",
   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_created_at",
   "type": "string",
   "required": false,
   "description": "Filter emails by maximum created_at date in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "deleted",
   "type": "boolean",
   "required": false,
   "description": "Whether to limit the results to expenses marked as deleted or not.",
   "default": false,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the expenses by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at and amount. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -created_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "expense_id": 1,
    "group_id": 1,
    "description": "string",
    "deleted": true,
    "receipt_file_name": "string",
    "created_at": "2019-01-01T00:00:00",
    "shares": [
     {
      "debtor": {
       "name": "string",
       "email": "user@example.com"
      },
      "debt_amount": 0.0
     }
    ],
    "creator": {
     "name": "string",
     "email": "user@example.com"
    },
    "payer": {
     "name": "string",
     "email": "user@example.com"
    },
    "paid_amount": 0.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "splitwise",
 "api_name": "record_payment",
 "path": "/payments",
 "method": "POST",
 "description": "Record a new payment for an expense. This only records payment on splitwise and does not move real money.",
 "parameters": [
  {
   "name": "payer_email",
   "type": "string",
   "required": true,
   "description": "Email of the user who made the payment.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "receiver_email",
   "type": "string",
   "required": true,
   "description": "Email of the user who received the payment.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "The amount of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "group_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the group to record the payment in.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "A short note or description of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "receipt_file_path",
   "type": "string",
   "required": false,
   "description": "Receipt file path to attach as an evidence of this payment made (e.g., snapshot of bank transfer, venmo, etc.)",
   "default": null,
   "constraints": []
  },
  {
   "name": "file_system_access_token",
   "type": "string",
   "required": false,
   "description": "Access token obtained from file_system app login. Only needed for attaching receipt file.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "payment_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
